import math


# --- generic helpers ---------------------------------------------------------

def _is_bool(x):
    return isinstance(x, bool)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _is_text(x):
    return isinstance(x, str) and x.strip() != ""


def _as_int(value, name, minimum=None):
    if not _is_int(value):
        raise ValueError("%s must be an integer" % name)
    if minimum is not None and value < minimum:
        raise ValueError("%s must be >= %d" % (name, minimum))
    return value


def _check_finite(value, where="payload"):
    """Recursively reject NaN / Infinity anywhere in the nested JSON value."""
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError("non-finite number in %s" % where)
    elif isinstance(value, dict):
        for k, v in value.items():
            _check_finite(v, "%s.%s" % (where, k))
    elif isinstance(value, list):
        for i, v in enumerate(value):
            _check_finite(v, "%s[%d]" % (where, i))


# --- recovery_chain ---------------------------------------------------------

def _parse_snapshot(raw, seen_ids):
    if not isinstance(raw, dict):
        raise ValueError("each snapshot must be an object")

    sid = raw.get("id")
    if not _is_text(sid):
        raise ValueError("snapshot id must be non-empty text")
    if sid in seen_ids:
        raise ValueError("duplicate snapshot id: %r" % sid)
    seen_ids.add(sid)

    kind = raw.get("kind")
    if kind not in ("full", "incremental"):
        raise ValueError("snapshot kind must be 'full' or 'incremental'")

    parent = raw.get("parent")
    if parent is not None and not _is_text(parent):
        raise ValueError("snapshot parent must be text or null")

    start = _as_int(raw.get("start"), "start", minimum=0)
    end = _as_int(raw.get("end"), "end")
    if end <= start:
        raise ValueError("end must be greater than start")

    cost = _as_int(raw.get("cost"), "cost", minimum=0)
    epoch = _as_int(raw.get("epoch"), "epoch", minimum=0)

    valid = raw.get("valid")
    if not isinstance(valid, bool):
        raise ValueError("valid must be a boolean")

    state_raw = raw.get("state")
    if not isinstance(state_raw, list):
        raise ValueError("state must be a list")

    state = []
    seen_keys = set()
    for item in state_raw:
        if not isinstance(item, dict):
            raise ValueError("each state item must be an object")
        key = item.get("key")
        if not _is_text(key):
            raise ValueError("state key must be non-empty text")
        if key in seen_keys:
            raise ValueError("duplicate state key: %r" % key)
        seen_keys.add(key)
        if "value" not in item:
            raise ValueError("state item missing 'value'")
        state.append({"key": key, "value": item["value"]})

    # Schema rules for a full snapshot.
    if kind == "full":
        if parent is not None or start != 0:
            raise ValueError("full snapshot must have parent null and start 0")

    return {
        "id": sid,
        "kind": kind,
        "parent": parent,
        "start": start,
        "end": end,
        "cost": cost,
        "epoch": epoch,
        "valid": valid,
        "state": state,
    }


def _check_parent_references(snapshots, by_id):
    for snap in snapshots:
        parent = snap["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("unknown parent: %r" % parent)

    # Detect any cycle in the parent graph.
    color = {}

    def visit(nid):
        state = color.get(nid, 0)
        if state == 1:
            raise ValueError("parent cycle detected")
        if state == 2:
            return
        color[nid] = 1
        parent = by_id[nid]["parent"]
        if parent is not None:
            visit(parent)
        color[nid] = 2

    for snap in snapshots:
        visit(snap["id"])


def transform(payloads, contract):
    if len(payloads) != 1:
        raise ValueError("recovery_chain expects exactly one input payload")

    payload = payloads[0]
    _check_finite(payload)
    if not isinstance(payload, dict):
        raise ValueError("recovery_chain payload must be an object")

    if "target" not in payload or "snapshots" not in payload:
        raise ValueError("recovery_chain payload must have 'target' and 'snapshots'")

    target = _as_int(payload["target"], "target", minimum=0)
    snapshots_raw = payload["snapshots"]
    if not isinstance(snapshots_raw, list):
        raise ValueError("snapshots must be a list")

    snapshots = []
    seen_ids = set()
    for raw in snapshots_raw:
        snapshots.append(_parse_snapshot(raw, seen_ids))

    by_id = {snap["id"]: snap for snap in snapshots}
    _check_parent_references(snapshots, by_id)

    # Recoverability memoization (topological by construction of the parent
    # graph, but memoized to be safe).
    memo = {}

    def recoverable(nid):
        if nid in memo:
            return memo[nid]
        snap = by_id[nid]
        result = False
        if snap["valid"] is True and snap["end"] <= target:
            if snap["kind"] == "full":
                result = True
            else:
                parent = snap["parent"]
                if parent is not None and recoverable(parent):
                    p = by_id[parent]
                    if p["end"] == snap["start"] and p["epoch"] == snap["epoch"]:
                        result = True
        memo[nid] = result
        return result

    for snap in snapshots:
        recoverable(snap["id"])

    def chain_and_cost(nid):
        snap = by_id[nid]
        if snap["kind"] == "full":
            return [snap["id"]], snap["cost"]
        parent_chain, parent_cost = chain_and_cost(snap["parent"])
        return parent_chain + [snap["id"]], parent_cost + snap["cost"]

    best = None
    for snap in snapshots:
        if not recoverable(snap["id"]):
            continue
        chain, cost = chain_and_cost(snap["id"])
        candidate = (snap["end"], cost, chain, snap)
        if best is None or (candidate[0], candidate[1], candidate[2]) < (best[0], best[1], best[2]):
            # (maximize end via ordering below) -- see selection key.
            pass

    # Selection: maximize end, then minimize cost, then lexicographically
    # smallest chain. Encode with a sortable key.
    candidates = []
    for snap in snapshots:
        if not recoverable(snap["id"]):
            continue
        chain, cost = chain_and_cost(snap["id"])
        candidates.append((snap["end"], cost, chain, snap))

    if not candidates:
        return {
            "name": contract["name"],
            "result": {
                "feasible": False,
                "chain": [],
                "snapshot_end": 0,
                "cost": 0,
                "state": [],
            },
        }

    _, _, chain, snap = min(candidates, key=lambda c: (-c[0], c[1], c[2]))
    state = sorted(snap["state"], key=lambda item: item["key"])
    return {
        "name": contract["name"],
        "result": {
            "feasible": True,
            "chain": chain,
            "snapshot_end": snap["end"],
            "cost": snap["cost"] + sum(by_id[cid]["cost"] for cid in chain[:-1]),
            "state": state,
        },
    }

