def _as_int(value, name, minimum=None):
    if not _is_int(value):
        raise ValueError("%s must be an integer" % name)
    if minimum is not None and value < minimum:
        raise ValueError("%s must be >= %d" % (name, minimum))
    return value


def _check_finite(value, where="payload"):
    """Recursively reject NaN / Infinity anywhere in the nested JSON value."""
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError("non-finite number in %s" % where)
    elif isinstance(value, dict):
        for k, v in value.items():
            _check_finite(v, "%s.%s" % (where, k))
    elif isinstance(value, list):
        for i, v in enumerate(value):
            _check_finite(v, "%s[%d]" % (where, i))


# --- transaction_replay -----------------------------------------------------

def _parse_record(raw):
    if not isinstance(raw, dict):
        raise ValueError("each record must be an object")

    lsn = _as_int(raw.get("lsn"), "lsn", minimum=0)
    epoch = _as_int(raw.get("epoch"), "epoch", minimum=0)

    tx = raw.get("tx")
    if not _is_text(tx):
        raise ValueError("record tx must be non-empty text")

    kind = raw.get("kind")
    if kind not in ("write", "commit", "abort"):
        raise ValueError("record kind must be 'write', 'commit' or 'abort'")

    record = {"lsn": lsn, "epoch": epoch, "tx": tx, "kind": kind}

    if kind == "write":
        key = raw.get("key")
        if not _is_text(key):
            raise ValueError("write key must be non-empty text")
        if "value" not in raw:
            raise ValueError("write record missing 'value'")
        seq = _as_int(raw.get("seq"), "seq", minimum=0)
        record["key"] = key
        record["value"] = raw["value"]
        record["seq"] = seq
    elif kind == "commit":
        count = _as_int(raw.get("count"), "count", minimum=0)
        record["count"] = count
    # abort: no additional required fields

    return record


def transform(payloads, contract):
    if len(payloads) != 1:
        raise ValueError("transaction_replay expects exactly one input payload")

    payload = payloads[0]
    _check_finite(payload)
    if not isinstance(payload, dict):
        raise ValueError("transaction_replay payload must be an object")

    if "checkpoint" not in payload or "records" not in payload:
        raise ValueError("transaction_replay payload must have 'checkpoint' and 'records'")

    checkpoint = _as_int(payload["checkpoint"], "checkpoint", minimum=-1)
    records_raw = payload["records"]
    if not isinstance(records_raw, list):
        raise ValueError("records must be a list")

    # Parse and validate every record (schema validation spans the whole
    # payload, including records beyond the scanned prefix).
    parsed = []
    for raw in records_raw:
        record = _parse_record(raw)
        parsed.append((record, raw))

    # Version conflict check over ALL (lsn, epoch) versions: identical content
    # is deduplicated, conflicting content is an error.
    groups = {}
    for record, raw in parsed:
        key = (record["lsn"], record["epoch"])
        if key in groups:
            if groups[key][1] != raw:
                raise ValueError(
                    "version conflict at lsn=%d epoch=%d" % (key[0], key[1])
                )
        else:
            groups[key] = (record, raw)

    unique = [groups[key][0] for key in groups]

    # The winning record for each LSN is the one with the highest epoch.
    winning = {}
    for record in unique:
        lsn = record["lsn"]
        if lsn not in winning or record["epoch"] > winning[lsn]["epoch"]:
            winning[lsn] = record

    # Scan the contiguous prefix beginning at checkpoint + 1.
    watermark = checkpoint
    cursor = checkpoint + 1

    tx_states = {}
    transactions = []
    incomplete = set()
    incomplete_commits = []

    while cursor in winning:
        record = winning[cursor]
        watermark = cursor
        tx = record["tx"]

        state = tx_states.get(tx)
        if state is not None and state["ended"]:
            raise ValueError("record after commit/abort for transaction %r" % tx)
        if state is None:
            state = {"writes": [], "ended": False}
            tx_states[tx] = state

        kind = record["kind"]
        if kind == "write":
            state["writes"].append((record["seq"], record["key"], record["value"]))
        elif kind == "commit":
            count = record["count"]
            seqs = sorted(w[0] for w in state["writes"])
            if seqs == list(range(count)):
                writes = [
                    {"key": key, "value": value}
                    for (_seq, key, value) in sorted(state["writes"], key=lambda w: w[0])
                ]
                transactions.append(
                    {
                        "tx": tx,
                        "commit_lsn": cursor,
                        "writes": writes,
                        "duration": len(writes),
                    }
                )
            else:
                incomplete_commits.append({"tx": tx, "commit_lsn": cursor})
                incomplete.add(tx)
            state["ended"] = True
        elif kind == "abort":
            state["ended"] = True

        cursor += 1

    # Un-ended transactions (writes with no commit/abort in the scanned prefix)
    # are incomplete.
    for tx, state in tx_states.items():
        if not state["ended"]:
            incomplete.add(tx)

    transactions.sort(key=lambda t: (t["commit_lsn"], t["tx"]))
    incomplete_commits.sort(key=lambda t: (t["commit_lsn"], t["tx"]))

    return {
        "name": contract["name"],
        "result": {
            "watermark": watermark,
            "transactions": transactions,
            "incomplete": sorted(incomplete),
            "incomplete_commits": incomplete_commits,
        },
    }

